window.products.push({"id":1119909,"name":"Qbedding Rattan Summer Sleeping Pad Mattress Topper & Pillow Shams Set, Queen, Brown, Cooling and Natural","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/51tcBVxAy5L._AC_.jpg","description":"Used for centuries in China & throughout Asia during warm summer months, to cool and comfort you while you sleep these mats are a great alternative to needing air conditioning. Crafted from Bing Si, an ancient Chinese blend of polyester fiber with a silky hand and Rattan stands, a natural material similar to wicker.","images":["https://m.media-amazon.com/images/I/51tcBVxAy5L._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Qbedding","source_asin":"B01E5SFHS2","category_path":"Home & Kitchen"},"sku":"BM-1119909","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B01E5SFHS2","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B01E5SFHS2","price_pending":true,"merchant_ready":false});
